if(kind==='saves'){renderImport(content);content.append(node('p','第一至第四章原型共用正式故事存檔，概念序章進度保留。讀檔會取代目前遊玩狀態。'+(window.mistDesktop?' 桌面每欄保存為獨立檔案，保留上一份有效備份。':'')));for(const slot of ['auto','1','2','3']){let saved=null;let errorText='';try{saved=readSave(saveStorage,slot);}catch{errorText='存檔無法讀取，原檔保留；請先備份後再決定是否覆寫。';}const row=node('article','');row.className='evidence-card';row.append(node('h3',slot==='auto'?'自動存檔':`手動欄位 ${slot}`),node('p',saved?`${chapterScenes[saved.scene].place} · 已做 ${saved.history.length} 次選擇`:(errorText||'空白或不相容的存檔')));if(slot!=='auto')row.append(button('儲存',()=>{if((saved||errorText)&&!confirm('要覆寫這個手動存檔嗎？'))return;if(persist(slot))panel('saves');}));const load=button('讀取',()=>{let fresh;try{fresh=readSave(saveStorage,slot);}catch{}if(!fresh){$('storage-status').textContent='存檔無法讀取。';return;}if(!confirm('讀檔會取代目前進度，要繼續嗎？'))return;state=fresh;persist();panelFocus.skipRestore();$('case-panel').close();open();});load.disabled=!saved;row.append(load);if(saved)row.append(button('匯出'+(slot==='auto'?'自動存檔':'欄位 '+slot),()=>downloadReport(exportSave(saved),'mist-save-'+slot+'.json')));if(window.mistDesktop){const inspect=button('預覽'+(slot==='auto'?'自動存檔':'欄位 '+slot)+'備份',()=>{try{const result=window.mistDesktop.backup('mist-chapter-v1-'+slot);const backup=result.data?decodeSave(result.data):null;const preview=node('div','');preview.append(node('p',backup?`備份內容：${chapterScenes[backup.scene].place} · ${backup.history.length} 次選擇`:'沒有可讀取的有效備份。'));if(backup)preview.append(button('恢復'+(slot==='auto'?'自動存檔':'欄位 '+slot)+'備份',()=>{if(!confirm(slot==='auto'?'恢復會取代自動存檔與目前進度，要繼續嗎？':'恢復會取代此手動欄位；目前遊玩進度不變，要繼續嗎？'))return;try{writeSave(saveStorage,slot,backup);if(slot==='auto'){state=backup;render();title();}panel('saves');}catch(error){preview.append(node('p','恢復未完成：'+error.message));}}));row.append(preview);inspect.disabled=true;}catch(error){row.append(node('p',error.message));}});row.append(inspect);}content.append(row);}}
