$('new-story').onclick=()=>{if(state&&!confirm('開始新第一章會取代自動存檔，手動存檔仍保留。要繼續嗎？'))return;state=newGame();persist();open();};$('continue-story').onclick=()=>{if(state)open();};document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>panel(b.dataset.panel));$('close-panel').onclick=()=>$('case-panel').close();window.addEventListener('mist-title',title);window.addEventListener('mist-restart',()=>{if($('chapter-screen').hidden)return;if(confirm('重新開始第一章？手動存檔仍保留。')){state=newGame();persist();open();}});title();

let previousTick=performance.now();let unsavedPlayMs=0;
setInterval(()=>{const now=performance.now();const delta=Math.min(2000,Math.max(0,Math.round(now-previousTick)));previousTick=now;const handoffOpen=$('case-panel').open&&activePanel==='handoff';if(!state||document.hidden||$('chapter-screen').hidden||(chapterScenes[state.scene].terminal&&!handoffOpen))return;state=recordPlayTime(state,delta,true,handoffOpen);unsavedPlayMs+=delta;const minutes=Math.floor(state.playTimeMs/60000);$('play-time').textContent=`本存檔前景遊玩時間：${minutes} 分鐘（只在此瀏覽器記錄，不包含背景分頁；不是章節目標時長）`;if(unsavedPlayMs>=30000){persist();unsavedPlayMs=0;}},1000);
document.addEventListener('visibilitychange',()=>{previousTick=performance.now();if(document.hidden&&state&&unsavedPlayMs>0){persist();unsavedPlayMs=0;}});
window.addEventListener('pagehide',()=>{if(state&&unsavedPlayMs>0){persist();unsavedPlayMs=0;}});

